const base = 'http://127.0.0.1:18080';
const health = await fetch("'`${base}/health`);
if (health.status !== 200 || JSON.stringify(await health.json()) !== '"'{\"status\":\"ok\"}') throw new Error('health failed');
const created = await fetch("'`${base}/api/projects`, {method:'"'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({name:'  Archive tasks  ')});
const project = await created.json();
const taskResponse = await fetch("'`${base}/api/projects/${project.id}/tasks`, {method:'"'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({title:' survive ')});
const task = await taskResponse.json();
await fetch("'`${base}/api/tasks/${task.id}`, {method:'"'PATCH', headers:{'content-type':'application/json'}, body:JSON.stringify({completed:true})});
await fetch("'`${base}/api/projects/${project.id}/archive`, {method:'"'PATCH', headers:{'content-type':'application/json'}, body:JSON.stringify({archived:true})});
let projects = await (await fetch("'`${base}/api/projects`)).json();
let tasks = await (await fetch(`${base}/api/projects/${project.id}/tasks`)).json();
if (!projects[0].archived || projects[0].completedCount !== 1 || projects[0].totalCount !== 1 || !tasks[0].completed) throw new Error('"'archive summary/task state failed');
await fetch("'`${base}/api/projects/${project.id}/archive`, {method:'"'PATCH', headers:{'content-type':'application/json'}, body:JSON.stringify({archived:false})});
projects = await (await fetch("'`${base}/api/projects`)).json();
if (projects[0].archived || projects[0].completedCount !== 1) throw new Error('"'restore failed');
console.log('health, create, archive, summary, tasks, and restore checks passed');
NODE
