const json=async(p,o)=>{const r=await fetch(base+p,o);if("'!r.ok)throw new Error(`${p}: ${r.status}`);return r.json()};
const project=(await json('"'/api/projects')).find(p=>p.name==='Archive tasks');
const tasks=await json("'`/api/projects/${project.id}/tasks`);
if(!project.archived||project.completedCount!==1||project.totalCount!==1||!tasks[0].completed)throw new Error('"'archived data failed');
await json("'`/api/projects/${project.id}/archive`,{method:'"'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({archived:false})});
const restored=(await json('/api/projects')).find(p=>p.id===project.id);
if(restored.archived||restored.completedCount"'!==1)throw new Error('"'restore failed');
console.log('health, archive summary, task persistence, and restore checks passed');
